#Requires -Version 5.1

$ErrorActionPreference = 'Stop'

$Script:Config = @{
    LocalUserName   = 'suporte'
    PasswordFile    = Join-Path $PSScriptRoot 'suporte.pwd'
    LogPath         = '\\172.20.100.2\Rede\1-CompartProducao\CIMED\LogsSetAdmLocal\LogSetAdmLocal.txt'
    AdminAccounts   = @('Administrador', 'Administrator')
    AdminGroups     = @('Administradores', 'Administrators')
}

function Test-IsElevated {
    $identity = [Security.Principal.WindowsIdentity]::GetCurrent()
    $principal = New-Object Security.Principal.WindowsPrincipal($identity)
    return $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
}

function Get-ProtectedPassword {
    param([Parameter(Mandatory)][string]$Path)

    if (-not (Test-Path -LiteralPath $Path)) {
        throw "Arquivo de credencial nao encontrado: $Path. Execute Install-SetAdmUser.ps1 primeiro."
    }

    $encoded = (Get-Content -LiteralPath $Path -Raw).Trim()
    if ([string]::IsNullOrWhiteSpace($encoded)) {
        throw "Arquivo de credencial vazio: $Path"
    }

    $protectedBytes = [Convert]::FromBase64String($encoded)
    $entropy = [byte[]]::new(0)

    $plainBytes = [Security.Cryptography.ProtectedData]::Unprotect(
        $protectedBytes,
        $entropy,
        [Security.Cryptography.DataProtectionScope]::LocalMachine
    )

    return [Text.Encoding]::UTF8.GetString($plainBytes)
}

function Invoke-NetCommand {
    param(
        [Parameter(Mandatory)][string[]]$Arguments
    )

    $output = & net.exe @Arguments 2>&1
    $exitCode = $LASTEXITCODE

    if ($exitCode -ne 0) {
        $message = ($output | Out-String).Trim()
        throw "Comando falhou (exit $exitCode): net $($Arguments -join ' ') :: $message"
    }

    return $output
}

function Test-LocalUserExists {
    param([Parameter(Mandatory)][string]$UserName)

    $null = & net.exe user $UserName 2>$null
    return $LASTEXITCODE -eq 0
}

function Set-LocalAdminUser {
    param(
        [Parameter(Mandatory)][string]$UserName,
        [Parameter(Mandatory)][string]$Password
    )

    $userExists = Test-LocalUserExists -UserName $UserName

    if (-not $userExists) {
        Invoke-NetCommand -Arguments @('user', $UserName, $Password, '/add') | Out-Null
    }
    else {
        Invoke-NetCommand -Arguments @('user', $UserName, $Password) | Out-Null
    }

    Invoke-NetCommand -Arguments @('user', $UserName, '/expires:never') | Out-Null

    foreach ($group in $Script:Config.AdminGroups) {
        $groupCheck = & net.exe localgroup $group 2>&1
        if ($LASTEXITCODE -ne 0) {
            continue
        }

        $memberList = ($groupCheck | Out-String)
        if ($memberList -notmatch "(^|\s)$([regex]::Escape($UserName))(\s|$)") {
            Invoke-NetCommand -Arguments @('localgroup', $group, $UserName, '/add') | Out-Null
        }
    }
}

function Disable-BuiltInAdministrator {
    foreach ($account in $Script:Config.AdminAccounts) {
        $null = & net.exe user $account 2>$null
        if ($LASTEXITCODE -eq 0) {
            Invoke-NetCommand -Arguments @('user', $account, '/active:no') | Out-Null
        }
    }
}

function Write-ExecutionLog {
    $timestamp = Get-Date -Format 'dd/MM/yyyy'
    $time = Get-Date -Format 'HH:mm:ss'
    $line = "$timestamp;$time;$env:COMPUTERNAME;$env:USERNAME"

    try {
        Add-Content -LiteralPath $Script:Config.LogPath -Value $line -Encoding ASCII -ErrorAction Stop
    }
    catch {
        Write-Warning "Nao foi possivel gravar log em $($Script:Config.LogPath): $($_.Exception.Message)"
    }
}

if (-not (Test-IsElevated)) {
    Write-Error 'Este script precisa ser executado como Administrador ou SYSTEM.'
    exit 1
}

try {
    $password = Get-ProtectedPassword -Path $Script:Config.PasswordFile

    Disable-BuiltInAdministrator
    Set-LocalAdminUser -UserName $Script:Config.LocalUserName -Password $password
    Write-ExecutionLog

    exit 0
}
catch {
    Write-Error $_.Exception.Message
    exit 1
}

