<#
.SYNOPSIS
    Script de inicializacao (GPO) para instalar e reaplicar SetAdmUser em silencio.

.DEPLOY
    Copie esta pasta inteira para o SYSVOL:
    \\SEU_DOMINIO.local\SYSVOL\SEU_DOMINIO.local\scripts\SetAdmUser\

    Arquivos necessarios no SYSVOL:
      - GPO-Startup-SetAdmUser.ps1
      - GPO-Startup-SetAdmUser.bat
      - Install-SetAdmUser.ps1
      - Set-AdmUser.ps1
      - set_adm_user.bat

    GPO > Configuracao do Computador > Politicas > Windows Settings > Scripts > Startup
    Adicione: GPO-Startup-SetAdmUser.bat
#>

$ErrorActionPreference = 'Stop'

$Config = @{
    InstallPath      = 'C:\ProgramData\CIMED\SetAdmUser'
    Password         = 'SUA_SENHA_AQUI'   # ALTERE: mesma senha em toda a rede (ou use SetAdmUser-Env + GPO env)
    SysvolSource     = $PSScriptRoot
    LogFile          = 'C:\ProgramData\CIMED\SetAdmUser\gpo-startup.log'
    TaskName         = 'CIMED_SetAdmUser'
    SkipScheduledTask = $true       # GPO ja roda a cada boot; tarefa e opcional
}

function Write-Log {
    param(
        [Parameter(Mandatory)][string]$Message,
        [ValidateSet('INFO', 'WARN', 'ERROR')]
        [string]$Level = 'INFO'
    )

    $line = '{0};{1};{2};{3}' -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'), $Level, $env:COMPUTERNAME, $Message
    $logDir = Split-Path -Parent $Config.LogFile

    if (-not (Test-Path -LiteralPath $logDir)) {
        New-Item -ItemType Directory -Path $logDir -Force | Out-Null
    }

    Add-Content -LiteralPath $Config.LogFile -Value $line -Encoding ASCII -ErrorAction SilentlyContinue
}

function Invoke-SetAdmUserApply {
    $mainScript = Join-Path $Config.InstallPath 'Set-AdmUser.ps1'

    if (-not (Test-Path -LiteralPath $mainScript)) {
        throw "Script principal nao encontrado: $mainScript"
    }

    & powershell.exe -NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File $mainScript
    $exitCode = $LASTEXITCODE

    if ($exitCode -ne 0) {
        throw "Set-AdmUser.ps1 falhou com codigo $exitCode"
    }
}

try {
    Write-Log 'Inicio do startup GPO SetAdmUser'

    $passwordFile = Join-Path $Config.InstallPath 'suporte.pwd'

    if (-not (Test-Path -LiteralPath $passwordFile)) {
        Write-Log 'Primeira execucao neste PC: iniciando instalacao silenciosa'

        $installScript = Join-Path $Config.SysvolSource 'Install-SetAdmUser.ps1'
        if (-not (Test-Path -LiteralPath $installScript)) {
            throw "Install-SetAdmUser.ps1 nao encontrado em $($Config.SysvolSource)"
        }

        $installArgs = @{
            Password    = $Config.Password
            InstallPath = $Config.InstallPath
            TaskName    = $Config.TaskName
            Silent      = $true
        }

        if ($Config.SkipScheduledTask) {
            $installArgs.SkipScheduledTask = $true
        }

        & powershell.exe -NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File $installScript @installArgs

        if ($LASTEXITCODE -ne 0) {
            throw "Install-SetAdmUser.ps1 falhou com codigo $LASTEXITCODE"
        }

        Write-Log 'Instalacao silenciosa concluida'
    }
    else {
        Write-Log 'Instalacao ja existente; reaplicando configuracao'
    }

    Invoke-SetAdmUserApply
    Write-Log 'Configuracao reaplicada com sucesso'
    exit 0
}
catch {
    Write-Log $_.Exception.Message 'ERROR'
    exit 1
}

#Requires -Version 5.1

function Get-EnvOrDefault {
    param(
        [Parameter(Mandatory)][string]$Name,
        [Parameter(Mandatory)][string]$Default
    )

    $value = [Environment]::GetEnvironmentVariable($Name, 'Machine')
    if ([string]::IsNullOrWhiteSpace($value)) {
        $value = [Environment]::GetEnvironmentVariable($Name, 'Process')
    }
    if ([string]::IsNullOrWhiteSpace($value)) {
        return $Default
    }

    return $value
}

function Get-EnvListOrDefault {
    param(
        [Parameter(Mandatory)][string]$Name,
        [Parameter(Mandatory)][string[]]$Default
    )

    $value = Get-EnvOrDefault -Name $Name -Default ''
    if ([string]::IsNullOrWhiteSpace($value)) {
        return $Default
    }

    return @($value.Split(',') | ForEach-Object { $_.Trim() } | Where-Object { $_ })
}

function Get-SetAdmUserConfig {
    param(
        [string]$ScriptRoot = $PSScriptRoot
    )

    $installPath = Get-EnvOrDefault -Name 'CIMED_SETADM_INSTALL_PATH' -Default 'C:\ProgramData\CIMED\SetAdmUser'
    $passwordFileName = Get-EnvOrDefault -Name 'CIMED_SETADM_PASSWORD_FILE' -Default 'suporte.pwd'

    if ([System.IO.Path]::IsPathRooted($passwordFileName)) {
        $passwordFile = $passwordFileName
    }
    else {
        $passwordFile = Join-Path $installPath $passwordFileName
    }

    $gpoLogFile = Get-EnvOrDefault -Name 'CIMED_SETADM_GPO_LOG_FILE' -Default (Join-Path $installPath 'gpo-startup.log')

    return [ordered]@{
        InstallPath       = $installPath
        LocalUserName     = Get-EnvOrDefault -Name 'CIMED_SETADM_LOCAL_USER' -Default 'suporte'
        PasswordFile      = $passwordFile
        LogPath           = Get-EnvOrDefault -Name 'CIMED_SETADM_LOG_PATH' -Default '\\172.20.100.2\Rede\1-CompartProducao\CIMED\LogsSetAdmLocal\LogSetAdmLocal.txt'
        AdminAccounts     = Get-EnvListOrDefault -Name 'CIMED_SETADM_ADMIN_ACCOUNTS' -Default @('Administrador', 'Administrator')
        AdminGroups       = Get-EnvListOrDefault -Name 'CIMED_SETADM_ADMIN_GROUPS' -Default @('Administradores', 'Administrators')
        TaskName          = Get-EnvOrDefault -Name 'CIMED_SETADM_TASK_NAME' -Default 'CIMED_SetAdmUser'
        SysvolSource      = Get-EnvOrDefault -Name 'CIMED_SETADM_SYSVOL_SOURCE' -Default $ScriptRoot
        GpoLogFile        = $gpoLogFile
        SkipScheduledTask = (Get-EnvOrDefault -Name 'CIMED_SETADM_SKIP_SCHEDULED_TASK' -Default 'true').ToLowerInvariant() -in @('1', 'true', 'yes', 'sim')
        ScriptRoot        = $ScriptRoot
    }
}

function Get-SetAdmUserPasswordFromEnv {
    $password = [Environment]::GetEnvironmentVariable('CIMED_SETADM_PASSWORD', 'Machine')
    if ([string]::IsNullOrWhiteSpace($password)) {
        $password = [Environment]::GetEnvironmentVariable('CIMED_SETADM_PASSWORD', 'Process')
    }

    if ([string]::IsNullOrWhiteSpace($password)) {
        throw 'Variavel de ambiente CIMED_SETADM_PASSWORD nao definida. Configure via GPO ou passe -Password no install.'
    }

    return $password
}

